private fun InstalledApp.updateFlagAgainstSnapshot(installedCode: Long): Boolean =
    if (latestVersionCode != null && latestVersionCode > 0L) {
        latestVersionCode > installedCode
    } else {
        !latestVersion.isNullOrBlank() &&
            VersionMath.isVersionNewer(latestVersion, installedVersion)
    }

fun InstalledApp.observeExternalInstall(
    versionName: String?,
    versionCode: Long,
): InstalledApp {
    val caughtUpToSnapshot =
        latestVersionCode != null && latestVersionCode > 0L && versionCode >= latestVersionCode
    return copy(
        installedVersionName = versionName,
        installedVersionCode = versionCode,
        installedVersion =
            if (caughtUpToSnapshot && latestVersion != null) latestVersion else installedVersion,
        isUpdateAvailable = updateFlagAgainstSnapshot(versionCode),
    )
}

